def bell_number(n):
    if n == 0:
        return 1
    elif n == 1:
        return 1
    else:
        bell = [0]*(n+1)
        bell[0] = 1
        bell[1] = 1
        for i in range(2, n+1):
            for j in range(i):
                bell[i] += bell[j] * bell[i-j-1]
        return bell[n]

