def get_total_number_of_sequences(m, n):
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        dp[i][1] = 1
    for j in range(2, n + 1):
        for i in range(2 * j, m + 1):
            dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1]
    return dp[m][n]

