def max_sum(arr):
    if not arr:
        return 0

    n = len(arr)
    increasing = [0] * n
    decreasing = [0] * n

    increasing[0] = arr[0]
    decreasing[n - 1] = arr[n - 1]

    for i in range(1, n):
        increasing[i] = max(increasing[i - 1], arr[i])
        decreasing[n - i - 1] = max(decreasing[n - i], arr[n - i - 1])

    return max(increasing + decreasing)

def lps(s):
    s = s.lower()
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return dp[0][n - 1]

