import re

def find_adverb_position(sentence):
    adverbs = ['clearly', 'obviously', 'apparently', 'undoubtedly', 'certainly', 'probably', 'possibly', 'clear', 'obvious', 'apparent', 'certain', 'likely', 'maybe']
    words = re.findall(r'\b\w+\b', sentence.lower())
    for i, word in enumerate(words):
        if word in adverbs:
            return (i, i + len(word), word)
    return None

