def largest_subset(nums):
    n = len(nums)
    dp = [0] * (1 << n)
    for mask in range(1, 1 << n):
        for i in range(n):
            if not (mask & (1 << i)) and (mask + (1 << i) < (1 << n)):
                if nums[i] % nums[nums[i:].index(nums[i] + nums[i]) + i] == 0:
                    dp[mask | (1 << i)] = max(dp[mask | (1 << i)], dp[mask] + 1)
    return max(dp)

